+    private int runsInColumn(int x, int y1, int y2) {
+        int runs = 0;
+        boolean painted = false;
+
+        for (int y = y1; y < y2; y++) {
+            boolean nowPainted = h.image.getArgb(x, y) != 0;
+
+            if (nowPainted && !painted) {
+                runs++;
+            }
+
+            painted = nowPainted;
+        }
+
+        return runs;
+    }
